(async()=>{try{const response=await fetch('./game-data.json');if(!response.ok)throw new Error('HTTP '+response.status);window.GAME_DATA=await response.json();const game=document.createElement('script');game.src='./game.js';game.onerror=()=>showLoadError('Could not load game.js. Check that all game files are in the same folder.');document.body.appendChild(game)}catch(error){showLoadError(location.protocol==='file:'?'This game now loads its data from JSON. Start a local web server in this folder, then open the game at http://localhost:8000.':'Could not load game-data.json. Check that all game files are in the same folder.')}function showLoadError(message){const box=document.createElement('pre');box.textContent=message;box.style.cssText='position:fixed;inset:20px;padding:20px;background:#161a10;color:#f3ead0;font:16px Arial,sans-serif;white-space:pre-wrap;z-index:9999';document.body.appendChild(box)}})();